interface DashboardToolbarProps {
  userName?: string
  roleLabel: string
  activeProgramsCount: number
  onOpenSettings: () => void
}

export function DashboardToolbar({
  userName,
  roleLabel,
  activeProgramsCount,
  onOpenSettings,
}: DashboardToolbarProps) {
  return (
    <div className="dashboard-toolbar">
      <div className="dashboard-toolbar-left">
        <span className="dashboard-toolbar-title">
          {userName} {roleLabel}님, 반갑습니다!
        </span>
        <span className="dashboard-toolbar-description">진행 프로젝트 {activeProgramsCount}건</span>
      </div>
      <div className="dashboard-toolbar-right">
        <AppButton
          type="primary"
          size="filter-wide"
          className="dashboard-toolbar-settings-btn"
          icon={<IconDashboardEdit />}
          onClick={onOpenSettings}
        >
          대시보드 설정
        </AppButton>
      </div>
    </div>
  )
}
